/**
 * Emits `packages/sdk/src/generated/vanilla-refs.ts`: the checked constructors behind the
 * `vanilla.*` namespace (SDK-12), one per registry `CONTENT_MANIFEST` and
 * `VANILLA_REF_EXTRAS` together expose.
 *
 * This is glue over a separate, install-derived package
 * (`@pdx-ts/stellaris-ids`, generated by `@pdx-ts/codegen-vanilla`, not this
 * codegen) — it never reads an install itself, and emits nothing but typed
 * wrappers around `{ id }`. `VanillaId`/`CheckedVanillaId`/`VanillaTrie` do
 * every bit of the actual checking, at compile time, against the tables that
 * package exports. `makeVanillaRef` also keeps private runtime provenance so
 * the Fold can distinguish a checked vanilla reference from a same-spelled
 * owned id without shipping every vanilla id as runtime data.
 */

import type { Emitter } from "../../emit/typescript.ts";
import { camelCase, docComment, spokenName } from "../../naming.ts";
import {
  HAND_WRITTEN_VANILLA_REFS,
  VANILLA_SUBTYPE_REFERENCE_PROJECTIONS,
} from "../../overlay/index.ts";
import {
  registryNameOf,
  type ContentManifestEntry,
  type VanillaRefExtra,
} from "../../policy/manifest.ts";

/** Generated vanilla-reference module text and its report totals. */
export interface VanillaRefsEmission {
  /** Complete generated `vanilla-refs.ts` module text. */
  readonly code: string;
  /** Ref type names (raw CWT `<type>` names) this emission used. */
  readonly refs: readonly string[];
  /** Number of registries emitted as checked constructor functions. */
  readonly checked: number;
  /** Number of registries emitted as navigable identifier tries. */
  readonly tries: number;
}

interface VanillaRefRow {
  /** Registry name: what the function or trie root is called after. */
  readonly registry: string;
  /** Public function or trie-root name. */
  readonly helper: string;
  /** Human-readable registry name used in public documentation. */
  readonly spoken: string;
  /**
   * The CWT reference the id satisfies — differs from `registry` only for the
   * `component_template` registries that share one CWT type via `as`, where it
   * is the qualified `component_template.utility_component_template` the rules
   * actually use. A vanilla id is the same kind of thing as a defined one, so
   * it wears the same brand `ContentItem` does.
   */
  readonly refSource: string;
  /** Whether the registry is large enough to get the navigable trie. */
  readonly oversized: boolean;
}

/**
 * Emits checked vanilla-reference constructors and tries for manifest and extra registries.
 * Every emitted reference brand is registered with the shared emitter for `refs.ts` generation.
 */
export function emitVanillaRefs(
  emitter: Emitter,
  manifest: readonly ContentManifestEntry[],
  extras: readonly VanillaRefExtra[],
  referenceNames: ReadonlyMap<string, string>
): VanillaRefsEmission {
  const rows: VanillaRefRow[] = [
    ...manifest.map((entry): VanillaRefRow => {
      const registry = registryNameOf(entry);
      return {
        registry,
        helper: camelCase(registry),
        spoken: spokenName(registry),
        refSource: referenceNames.get(registry) ?? entry.type,
        oversized: entry.oversized ?? false,
      };
    }),
    ...extras.map((extra): VanillaRefRow => ({
      registry: extra.type,
      helper: camelCase(extra.type),
      spoken: spokenName(extra.type),
      refSource: extra.type,
      oversized: extra.oversized ?? false,
    })),
    ...VANILLA_SUBTYPE_REFERENCE_PROJECTIONS.map((projection): VanillaRefRow => ({
      registry: `${projection.registry}.${projection.subtype}`,
      helper: camelCase(projection.subtype),
      spoken: spokenName(projection.subtype),
      refSource: `${projection.registry}.${projection.subtype}`,
      oversized: false,
    })),
  ];

  const chunks = rows.map((row) => emitRow(emitter, row));
  for (const handWritten of HAND_WRITTEN_VANILLA_REFS) {
    // Every row here is asserted against the one hand-written emission this
    // function actually has (SDK-260): a renamed or added row with nothing to
    // emit it fails loudly instead of silently emitting nothing.
    if (handWritten.registry !== "event") {
      throw new Error(
        `HAND_WRITTEN_VANILLA_REFS names "${handWritten.registry}", which emitVanillaRefs has no ` +
          "hand-written emission for — add one or retire the row"
      );
    }
    chunks.push(emitEventRow());
  }

  chunks.push(emitLocalizationRow());

  return {
    code: chunks.join("\n"),
    refs: [...new Set(rows.map((row) => row.refSource))].sort(),
    checked: rows.filter((row) => !row.oversized).length,
    tries: rows.filter((row) => row.oversized).length + HAND_WRITTEN_VANILLA_REFS.length,
  };
}

/**
 * The one `vanilla.*` member that is not a registry: a re-export of the
 * hand-written `vanilla.localization` (SDK-307).
 *
 * No `CONTENT_MANIFEST` or `VANILLA_REF_EXTRAS` row could produce it, and it is
 * not a graft of the mechanical checked-id pair either — a localization key has
 * no registry, no `Ref` brand, and no id set to check a union against. Its
 * 149,217 keys are checked at build time against a `Set`, which this generator
 * cannot emit because it never reads an install. So the inventory and the
 * lookup live where they belong and this file states only what the namespace
 * holds, which is the part this generator does own. The doc comment stays on
 * the re-exported declaration, where a hover over `vanilla.localization`
 * resolves it.
 */
function emitLocalizationRow(): string {
  return 'export { vanillaLocalizationRef as localization } from "../identifiers/vanilla-localization.ts";\n';
}

function emitEventRow(): string {
  return (
    docComment([
      "Vanilla event ids, navigable by namespace and local id.",
      "The identifier package supplies exact EventRef scope and kind types.",
    ]) + 'export const event: VanillaTrie<"event"> = makeEventTrie();\n'
  );
}

function emitRow(emitter: Emitter, row: VanillaRefRow): string {
  // Every ref this file names must survive into `refs.ts` even if nothing
  // else in the rules happens to reference it — `sound`, `sound_effect`, and
  // `resource` are ref-only extras with no other emitter touching them.
  emitter.usedRefs.add(row.refSource);
  const refType = emitter.refTypeName(row.refSource);
  const name = row.helper;
  const key = JSON.stringify(row.registry);
  const spoken = row.spoken;

  if (!row.oversized) {
    return (
      docComment([
        `A checked reference to a vanilla ${spoken} id.`,
        "",
        "Checked against @pdx-ts/stellaris-ids's id set for this registry, so",
        "a misspelled id is a compile error. Zero runtime validation — this",
        "only constructs the branded reference the rest of the SDK accepts.",
      ]) +
      `export function ${name}<const Id extends VanillaId<${key}>>(\n` +
      "  id: Id\n" +
      `): ${refType} & { readonly id: Id } {\n` +
      `  return makeVanillaRef(id) as ${refType} & { readonly id: Id };\n` +
      "}\n"
    );
  }

  return (
    docComment([
      `Vanilla ${spoken} ids, both navigable and checked.`,
      "",
      `\`${name}.<file>...<id>\` descends buckets named after the vanilla`,
      "files and directories these ids are defined in, to a leaf spelling the",
      "id verbatim — the buckets are navigation only and no part of the id.",
      "",
      `\`${name}(id)\` accepts a string copied straight from a game file,`,
      "checked against the same id set with no completion menu ever built.",
      "",
      "Both forms check against @pdx-ts/stellaris-ids's id set for this",
      "registry, so a misspelled id is a compile error. Zero runtime",
      "validation.",
    ]) +
    `export const ${name}: VanillaTrie<${key}> &\n` +
    "  (<const Id extends string>(\n" +
    `    id: Id & CheckedVanillaId<${key}, Id>\n` +
    `  ) => ${refType} & { readonly id: Id }) = makeIdTrie(${key});\n`
  );
}
